def handle(app, svc):
    """Handler for the Quillon partner (ticket KF-20).

    Quillon runs the network's current API version (v2):
        {"api_version": 2, "result": {"outcome": "approved"|"declined"|"manual_review",
                                      "credit_limit": int}}
    A v1 fallback (decision/limit) is kept for safety.

    Mapping (order matters):
      1. decline  -> "decline" (stays a decline even if self_employed > 7000)
      2. manual_review / refer -> "queue_review" (never decline)
      3. approve  -> network referral rule: self_employed AND requested_limit > 7000
                     forces "queue_review"; otherwise "issue" with the returned limit.
    """
    resp = svc.apply(app)
    if not isinstance(resp, dict):
        resp = {}

    # ---- Parse outcome: prefer v2, fall back to v1 ----
    outcome = None
    limit = 0

    result = resp.get("result")
    if isinstance(result, dict) and "outcome" in result:
        # API v2
        outcome = str(result.get("outcome"))
        cl = result.get("credit_limit")
        if isinstance(cl, (int, float)):
            limit = int(cl)
    elif "decision" in resp:
        # API v1 (legacy)
        outcome = str(resp.get("decision"))
        lm = resp.get("limit")
        if isinstance(lm, (int, float)):
            limit = int(lm)

    # Normalize vocabulary
    outcome = outcome.lower()
    if outcome in ("declined", "decline"):
        action = "decline"
        return {"action": action, "limit": 0}
    if outcome in ("manual_review", "refer"):
        action = "queue_review"
        return {"action": action, "limit": 0}
    if outcome in ("approved", "approve"):
        # Network referral rule: self_employed + requested_limit > 7000 -> queue_review
        employment = str(app.get("employment", "")).lower()
        try:
            requested_limit = int(app.get("requested_limit", 0))
        except (TypeError, ValueError):
            requested_limit = 0
        if employment == "self_employed" and requested_limit > 7000:
            return {"action": "queue_review", "limit": 0}
        return {"action": "issue", "limit": limit}

    # Unknown/undecidable outcome -> route to review rather than guessing
    return {"action": "queue_review", "limit": 0}
